{
  "summary": "Verify whether the two Acme Cloud Services September 2026 invoices are duplicates by checking invoice records and contract terms, then draft a dispute message to Acme if confirmed.",
  "reply_type": "vendor_email",
  "steps": [
    {
      "id": 1,
      "agent": "retriever",
      "task": "List company documents to locate both Acme Cloud Services invoices for September 2026 hosting and the Acme services contract/agreement. Read all three documents to compare invoice numbers, dates, amounts, billing periods, and line-item descriptions to determine if the two invoices are duplicates (same service period/charges). If invoice amounts are in USD, use the currency converter to express amounts in company reporting currency for clarity.",
      "why": "The retriever must gather the actual invoice details and contract terms to confirm duplication before any dispute can be drafted."
    },
    {
      "id": 2,
      "agent": "executor",
      "task": "Using the confirmed facts (invoice numbers, dates, amounts, billing period overlap) from step 1, draft a formal dispute email to Acme Cloud Services notifying them of the apparent duplicate invoice, citing the specific invoice numbers/dates/amounts, referencing the contract billing terms, and requesting confirmation/cancellation or credit for the duplicate charge.",
      "why": "The executor compiles the gathered facts into the final vendor-facing dispute message for human review and approval."
    }
  ],
  "escalate": n
